<script setup lang="ts">
import { useQuery, useQueryClient } from '@tanstack/vue-query'
import type { Project } from '~~/shared/types/projects'
import { projectProfile, projectStatuses } from '~~/shared/utils/project-workspace'
const props=defineProps<{projects:Project[]}>(),emit=defineEmits<{settings:[project:Project]}>()
const auth=useAuthStore(),client=useQueryClient()
const {search,status,view,folder,archived,favorites}=toRefs(useSavedFilters('projects',{search:'',status:'all',view:'grid' as 'grid'|'list',folder:'all',archived:false as boolean,favorites:false as boolean}))
const folderOpen=ref(false),folderName=ref(''),busy=ref(false),error=ref(''),target=ref<Project|null>(null),action=ref(''),folderTarget=ref('root')
const folders=useQuery({queryKey:computed(()=>['account',auth.user?.id,'project-folders']),queryFn:()=>sharedRequest<{id:string;name:string}[]>('/api/projects/folders'),retry:false})
const folderOptions=computed(()=>[{label:'Без папки',value:'root'},...(folders.data.value??[]).map(f=>({label:f.name,value:f.id}))])
const rows=computed(()=>props.projects.filter(p=>Boolean(p.profile?.archived)===archived.value&&(!favorites.value||p.favorite)&&(folder.value==='all'||(p.folderId||'root')===folder.value)&&(status.value==='all'||projectProfile(p).status===status.value)&&`${p.name} ${p.members.find(m=>m.userId===p.ownerId)?.fullName??''}`.toLowerCase().includes(search.value.toLowerCase().trim())))
const date=(p:Project)=>new Intl.DateTimeFormat('ru-RU',{dateStyle:'medium'}).format(new Date(p.profile?.startOn?p.profile.startOn+'T12:00:00':p.createdAt))
async function run(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';try{await fn();await Promise.all([client.invalidateQueries({queryKey:['account',auth.user?.id,'projects']}),folders.refetch()]);target.value=null;folderOpen.value=false;folderName.value=''}catch(e:any){error.value=e?.data?.message||'Не удалось сохранить';}finally{busy.value=false}}
function choose(p:Project,value:string){if(value==='rename'){emit('settings',p);return}target.value=p;action.value=value;folderTarget.value=p.folderId||'root';error.value=''}
function confirm(){const p=target.value;if(!p)return;void run(async()=>{const result=await sharedRequest<{id?:string}>(`/api/projects/${p.id}/workspace`,{method:'POST',body:{action:action.value,revision:action.value==='move'?undefined:p.revision,...(action.value==='move'?{data:{folderId:folderTarget.value==='root'?null:folderTarget.value}}:action.value==='archive'?{data:{archived:!archived.value}}:{})}});if(result.id)await navigateTo(`/projects/${result.id}`)})}
const titles:Record<string,string>={move:'Перенести в папку',duplicate:'Дублировать проект',archive:'Изменить архив проекта',delete:'Удалить проект'}
</script>
<template>
 <section class="directory">
  <div class="directory-toolbar"><UInput v-model="search" icon="i-lucide-search" placeholder="Найти проект или владельца" aria-label="Поиск проектов"/><USelect v-model="status" :items="[{label:'Все статусы',value:'all'},...projectStatuses]" aria-label="Статус проекта"/><UButton icon="i-lucide-folder-plus" label="Добавить папку" color="neutral" variant="outline" @click="folderOpen=true"/><UButton icon="i-lucide-grid-2x2" aria-label="Плитка" :variant="view==='grid'?'solid':'outline'" @click="view='grid'"/><UButton icon="i-lucide-list" aria-label="Список" :variant="view==='list'?'solid':'outline'" @click="view='list'"/></div>
  <div class="directory-folders"><USelect v-model="folder" :items="[{label:'Все папки',value:'all'},...folderOptions]" aria-label="Папка"/><UCheckbox v-model="favorites" label="Избранное"/><UCheckbox v-model="archived" label="Архив"/><small>Проектов: {{rows.length}}</small></div>
  <UAlert v-if="error" color="error" :description="error"/><UAlert v-if="folders.error.value" color="error" title="Не удалось загрузить папки" :actions="[{label:'Повторить',onClick:()=>folders.refetch()}]"/>
  <div class="project-cards" :class="{'as-list':view==='list'}"><article v-for="p in rows" :key="p.id"><NuxtLink :to="`/projects/${p.id}`"><img v-if="p.profile?.avatar" :src="p.profile.avatar" alt=""/><UIcon v-else name="i-lucide-folder-kanban"/><div class="project-name"><h2>{{p.favorite?'★ ':''}}{{p.name}}</h2><small>{{folders.data.value?.find(f=>f.id===p.folderId)?.name||'Без папки'}}</small></div><UBadge color="neutral" variant="soft">{{projectStatuses.find(s=>s.value===projectProfile(p).status)?.label}}</UBadge><div><small>Дата</small><span>{{date(p)}}</span></div><div><small>Владелец</small><span>{{p.members.find(m=>m.userId===p.ownerId)?.fullName||'—'}}</span></div></NuxtLink><UDropdownMenu :items="[{label:'Переименовать',icon:'i-lucide-pencil',disabled:p.permission==='viewer',onSelect:()=>choose(p,'rename')},{label:'Дублировать',icon:'i-lucide-copy',onSelect:()=>choose(p,'duplicate')},{label:'Перенести в папку',icon:'i-lucide-folder-input',onSelect:()=>choose(p,'move')},{label:archived?'Восстановить из архива':'В архив',icon:'i-lucide-archive',disabled:p.permission!=='owner',onSelect:()=>choose(p,'archive')},{label:'Удалить',icon:'i-lucide-trash',color:'error',disabled:p.permission!=='owner',onSelect:()=>choose(p,'delete')}]"><UButton icon="i-lucide-ellipsis" color="neutral" variant="ghost" :aria-label="`Настройки проекта ${p.name}`"/></UDropdownMenu></article></div><p v-if="!rows.length" class="directory-empty">По выбранным условиям проектов нет.</p>
  <UModal v-model:open="folderOpen" title="Добавить папку" description="Папки и расположение проектов сохраняются для вашей учётной записи." :dismissible="!busy"><template #body><form class="space-y-4" @submit.prevent="run(()=>sharedRequest('/api/projects/folders',{method:'POST',body:{name:folderName}}))"><UInput v-model="folderName" placeholder="Название папки" aria-label="Название папки" :maxlength="120" required class="w-full"/><UAlert v-if="error" color="error" :description="error"/><UButton type="submit" label="Добавить" :loading="busy" :disabled="!folderName.trim()"/></form></template></UModal>
  <UModal :open="!!target" :title="titles[action]" :dismissible="!busy" @update:open="value=>{if(!value)target=null}"><template #body><div class="space-y-4"><p>{{target?.name}}</p><USelect v-if="action==='move'" v-model="folderTarget" :items="folderOptions" aria-label="Целевая папка" class="w-full"/><p v-if="action==='duplicate'">Будет создана копия обзора и состава участников. Задачи, договоры, вложения и финансовые данные остаются в исходном проекте.</p><p v-if="action==='delete'">Проект, его экономика и доска задач будут удалены. Это действие нельзя отменить.</p><UAlert v-if="error" color="error" :description="error"/><UButton :label="action==='delete'?'Удалить навсегда':'Подтвердить'" :color="action==='delete'?'error':'primary'" :loading="busy" @click="confirm"/></div></template></UModal>
 </section>
</template>
<style scoped>
.directory{display:grid;gap:24px}.directory-toolbar,.directory-folders{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.directory-toolbar>:first-child{flex:1;min-width:220px}.directory-folders small{margin-left:auto;color:#94a3b8}.project-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:20px}.project-cards article{border:1px solid #e2e8f0;border-radius:22px;background:#fff;position:relative;padding:24px}.project-cards article>:last-child{position:absolute;right:12px;top:12px}.project-cards a{display:flex;flex-direction:column;gap:18px}.project-cards img,.project-cards a>.iconify{height:48px;width:48px;object-fit:cover;border-radius:12px}.project-cards h2{font-size:20px;font-weight:600;padding-right:15px;overflow-wrap:anywhere}.project-cards small{display:block;font-size:12px;color:#94a3b8;margin-bottom:4px}.project-cards span{color:#475569}.project-cards.as-list{grid-template-columns:1fr}.as-list a{flex-direction:row;align-items:center;padding-right:30px}.as-list a>div{flex:1;min-width:0}.directory-empty{padding:50px;text-align:center;color:#94a3b8}@media(max-width:750px){.as-list a{flex-wrap:wrap}.as-list .project-name{min-width:65%}.project-cards article{padding:20px}}
</style>
